  "recovered_c": "uint64_t fn_05(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len < 0x17 || out_cap < 8) {\n    return 0xffffffffffffffff;\n  }\n  uint32_t state1 = arg;\n  uint32_t state2 = arg;\n  for (size_t i = 0; i < len; i++) {\n    state1 += in[i] * 0x10 + (state2 >> 5) + (state2 & 0xff);\n    state2 += state1 * 0x10 + (state1 >> 5) + (state1 & 0xff);\n  }\n  out[0] = (state1 >> 24) & 0xff;\n  out[1] = (state1 >> 16) & 0xff;\n  out[2] = (state1 >> 8) & 0xff;\n  out[3] = state1 & 0xff;\n  out[4] = (state2 >> 24) & 0xff;\n  out[5] = (state2 >> 16) & 0xff;\n  out[6] = (state2 >> 8) & 0xff;\n  out[7] = state2 & 0xff;\n  return 8;\n}"
